import{_ as t,o as e,c as l,a2 as r}from"./chunks/framework.F7eQ-ohH.js";const i="/bzygq/assets/quesion_imgs_eae75240513741e0b110b7cd5a7c63a8.D1mDwWW9.png",d="/bzygq/assets/quesion_imgs_b228d20cf72e4a81a25cc819520fa3e1.BnGexlRL.png",u=JSON.parse('{"title":"5、数据库安全性","description":"","frontmatter":{},"headers":[],"relativePath":"科技岗专业课/数据库系统/5、数据库安全性.md","filePath":"科技岗专业课/数据库系统/5、数据库安全性.md","lastUpdated":1788883925000}'),o={name:"科技岗专业课/数据库系统/5、数据库安全性.md"};function h(n,a,s,b,S,c){return e(),l("div",null,[...a[0]||(a[0]=[r('<h1 id="_5、数据库安全性" tabindex="-1">5、数据库安全性 <a class="header-anchor" href="#_5、数据库安全性" aria-label="Permalink to &quot;5、数据库安全性&quot;">​</a></h1><p><strong>数据库安全性</strong></p><h2 id="安全性概述" tabindex="-1">安全性概述 <a class="header-anchor" href="#安全性概述" aria-label="Permalink to &quot;安全性概述&quot;">​</a></h2><h2 id="数据库安全性" tabindex="-1">数据库安全性 <a class="header-anchor" href="#数据库安全性" aria-label="Permalink to &quot;数据库安全性&quot;">​</a></h2><p>数据库安全性是指保护数据库免受未授权的访问、篡改、破坏或泄露，确保数据的保密性、完整性和可用性。在信息化时代，数据库作为数据存储和管理的核心，其安全性直接关系到组织的业务连续性、隐私保护及合规要求，主要分为四个方面：</p><ol><li>保密性（Confidentiality）：确保数据仅被授权用户访问，防止敏感信息（如用户隐私、商业机密）泄露。</li><li>完整性（Integrity）：保证数据的准确性和一致性，防止未授权的修改或数据损坏。</li><li>可用性（Availability）：确保授权用户在需要时可以正常访问和使用数据，避免因攻击（如拒绝服务攻击）或故障导致数据不可用。</li><li>不可否认性（Non-Repudiation）：通过技术手段（如数字签名）确保用户无法否认其操作行为，常用于审计和追责。</li></ol><h2 id="数据库的不安全因素" tabindex="-1">数据库的不安全因素 <a class="header-anchor" href="#数据库的不安全因素" aria-label="Permalink to &quot;数据库的不安全因素&quot;">​</a></h2><ol><li>人为因素（含内部与外部威胁）：包括黑客利用 SQL 注入、弱密码等漏洞非法获取权限的未授权访问，员工或管理员滥用权限进行的数据篡改、泄露等恶意操作，以及授权用户误删表、错误导入数据等操作失误导致的损失。</li><li>系统与技术漏洞：涵盖 MySQL、Oracle 等数据库管理系统本身的安全缺陷（如缓冲区溢出、权限校验漏洞），数据库参数配置不当（如开放公网访问、默认账号未修改），以及通过网络嗅探、中间人攻击窃取通信数据的网络攻击行为。</li><li>物理与环境风险：主要指服务器硬盘损坏、机房断电、自然灾害等硬件故障引发的数据丢失，以及未经授权人员进入机房窃取硬件、篡改数据的物理入侵风险。</li><li>合规与管理缺陷：包括权限分配不合理（如过度授权）、未遵循 “最小权限原则” 的权限管理混乱问题，缺乏操作日志记录导致安全事件无法追溯的审计缺失，以及违反 GDPR、《个人信息保护法》等法规引发的法律风险。</li></ol><h2 id="数据库安全性模型" tabindex="-1">数据库安全性模型 <a class="header-anchor" href="#数据库安全性模型" aria-label="Permalink to &quot;数据库安全性模型&quot;">​</a></h2><p><img src="'+i+'" alt=""></p><p>数据库安全性模型是一个分层递进的纵深安全体系，从用户接入到数据存储共分为四个核心防护层级，层层拦截风险，全方位保障数据库安全：</p><ol><li>用户标识与鉴定层（最外层防线）</li></ol><p>这是用户与系统交互的第一道关卡，核心作用是验证用户身份的合法性。用户需提供唯一的身份标识（如用户名），系统会与预存的合法用户信息进行核对，只有通过鉴定的用户才能进入后续环节。该过程可根据安全需求重复多次（如多轮验证），有效防止未授权用户伪装身份，是数据库安全的 “入口过滤器”。</p><ol><li>DBMS 存取权限控制层（核心防护层）</li></ol><p>在用户通过身份鉴定后，数据库管理系统（DBMS）会基于预设的权限策略，对用户的操作请求进行细粒度校验。它会判断用户是否具备对目标数据的存取、修改、删除等权限，严格遵循 “最小权限原则”，确保用户仅能访问和操作其职责范围内的数据，避免过度授权带来的风险，是数据库安全的核心控制环节。</p><ol><li>操作系统安全保护层（底层支撑层）</li></ol><p>DBMS 的运行依赖于操作系统，这一层主要负责保护数据库的底层运行环境。它通过访问控制列表、进程隔离等机制，防止对数据库服务器的非法访问，拦截恶意进程，保障系统资源的安全分配，从而抵御针对操作系统的攻击，避免攻击者通过攻陷操作系统来窃取或破坏数据库，是数据库安全的 “底层护城河”。</p><ol><li>数据库密码存储层（最终数据层）</li></ol><p>这是数据存储的最后一道防线，核心是对数据库中的敏感数据（尤其是用户密码等核心信息）进行加密存储。通过哈希算法、对称 / 非对称加密等技术，确保数据在静态存储状态下的保密性，即使攻击者突破了前面的防护层，也无法直接获取明文数据，是数据安全的 “最终保险箱”。</p><h2 id="真题" tabindex="-1">真题 <a class="header-anchor" href="#真题" aria-label="Permalink to &quot;真题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>【国家电网】以下属于实现数据库系统安全性的主要技术和方法的是（ ）A.存取控制技术B.视图技术C.审计技术D.出入机房登记和加锁答案：ABC解析：实现数据库系统安全性的主要技术包括存取控制技术、视图技术、审计技术等，出入机房登记属于环境级安全措施，不是数据库系统本身的技术。</th></tr></thead></table><table tabindex="0"><thead><tr><th>【国家电网2019】数据库的安全性是指保护数据库以防止不合法的使用所造成的数据泄露、更改或破坏。所以通过提供授权功能来控制不同用户访问数据的权限，是为了实现数据库的()；A. 完整性B. 安全性C. 并发控制D. 恢复答案：B解析：数据库的安全性是指保护数据库以防止不合法的使用所造成的数据泄露、更改或破坏。通过提供授权功能控制不同用户访问数据的权限，是实现数据库安全性的手段</th></tr></thead></table><h2 id="存取控制" tabindex="-1">存取控制 <a class="header-anchor" href="#存取控制" aria-label="Permalink to &quot;存取控制&quot;">​</a></h2><h2 id="数据库存取控制概述" tabindex="-1">数据库存取控制概述 <a class="header-anchor" href="#数据库存取控制概述" aria-label="Permalink to &quot;数据库存取控制概述&quot;">​</a></h2><p>数据库存取控制是保障数据安全的核心机制，其核心逻辑是通过限定用户对数据库对象（如表、视图、字段等）的访问权限，在保障数据可用性的同时，严格遵循 “最小权限原则”—— 即用户仅能获得完成任务所需的最低权限，以此防止未授权的信息泄露、篡改或破坏。这一机制是数据库安全体系中承上启下的关键环节，既承接用户身份鉴定的结果，又为后续数据访问建立了明确的权限边界。</p><h2 id="数据库存取控制的主要模型" tabindex="-1">数据库存取控制的主要模型 <a class="header-anchor" href="#数据库存取控制的主要模型" aria-label="Permalink to &quot;数据库存取控制的主要模型&quot;">​</a></h2><ol><li>自主存取控制（DAC）该模型的核心思想是赋予数据对象所有者（如数据库管理员或表的创建者）自主分配权限的能力，通过访问控制列表（ACL）记录用户与权限的映射关系。例如，数据库管理员可授权用户 A 对 “员工表” 拥有查询权限，而用户 A 也可将该权限转授给用户 B。这种模型的优势在于灵活性高，能快速适配业务变化，但也存在权限传递引发的安全风险，比如误授权可能导致敏感数据被过度扩散。</li><li>强制存取控制（MAC）与 DAC 的自主授权不同，MAC 由系统主导权限分配，核心是为数据对象和用户分别预设安全标签（如机密级、秘密级、公开级），仅当用户的安全级别高于或等于数据对象的安全级别时，才允许访问。例如，绝密级用户可访问秘密级和公开级数据，但秘密级用户无法访问绝密级数据。这类模型安全性极强，权限不可自主修改，因此广泛应用于军事、政府等对数据保密性要求极高的场景。</li><li>基于角色的存取控制（RBAC）RBAC 的核心思路是 “权限绑定角色，用户关联角色”，通过定义角色（如 “管理员”“普通用户”“审计员”）并为角色分配对应权限（如管理员可执行增删改查全操作，普通用户仅可查询），再将用户关联到相应角色来实现权限管控。这种方式大幅简化了复杂组织结构中的权限管理，支持批量分配与回收权限，尤其适合企业级数据库场景，能有效减少直接绑定用户与权限带来的管理冗余。</li></ol><h2 id="数据库存取控制的实现" tabindex="-1">数据库存取控制的实现 <a class="header-anchor" href="#数据库存取控制的实现" aria-label="Permalink to &quot;数据库存取控制的实现&quot;">​</a></h2><p>用户认证与授权和权限类型这是存取控制的前置环节，认证负责验证用户身份的合法性，常见方式包括用户名 / 密码、生物识别、JWT 令牌等；授权则在认证通过后，确定用户可对数据执行的具体操作，通常通过 SQL 语句或数据库管理工具完成配置</p><ul><li>认证（Authentication）：验证用户身份，常见方式包括用户名/密码、生物识别、令牌（如JWT）等。</li><li>授权（Authorization）：确定用户可执行的操作，通过SQL语句或数据库管理工具实现。</li></ul><p>数据库系统定义了一系列标准化权限，涵盖数据操作的全场景：</p><table tabindex="0"><thead><tr><th>权限类型</th><th>描述</th></tr></thead><tbody><tr><td>SELECT</td><td>查询数据（如表、视图中的内容）</td></tr><tr><td>INSERT</td><td>插入新数据</td></tr><tr><td>UPDATE</td><td>修改已有数据</td></tr><tr><td>DELETE</td><td>删除数据</td></tr><tr><td>EXECUTE</td><td>执行存储过程或函数</td></tr><tr><td>ALL PRIVILEGES</td><td>包含所有操作权限（需谨慎使用）</td></tr><tr><td>GRANT OPTION</td><td>允许用户将权限转授给其他用户（仅在DAC模型中有效）</td></tr></tbody></table><p>如上表所示，基础操作权限包括查询（SELECT）、插入（INSERT）、修改（UPDATE）、删除（DELETE），以及执行存储过程的（EXECUTE）权限；高级权限包含代表所有操作权限的（ALL PRIVILEGES，需谨慎分配），和允许用户转授权限的（GRANT OPTION，仅在 DAC 模型中生效）。</p><h3 id="sql中的权限管理语句" tabindex="-1">SQL中的权限管理语句 <a class="header-anchor" href="#sql中的权限管理语句" aria-label="Permalink to &quot;SQL中的权限管理语句&quot;">​</a></h3><ul><li>授权（GRANT）：</li></ul><table tabindex="0"><thead><tr><th>SQLGRANT SELECT, INSERT ON employees TO &#39;user1&#39;@&#39;localhost&#39;; -- 授予查询和插入权限GRANT ALL PRIVILEGES ON company.* TO &#39;admin&#39;@&#39;%&#39;; -- 授予数据库所有权限</th></tr></thead></table><ul><li>回收权限（REVOKE）：</li></ul><table tabindex="0"><thead><tr><th>SQLREVOKE UPDATE ON employees FROM &#39;user1&#39;@&#39;localhost&#39;; -- 回收更新权限</th></tr></thead></table><ul><li>查看权限（SHOW GRANTS）：</li></ul><table tabindex="0"><thead><tr><th>SQLSHOW GRANTS FOR &#39;user1&#39;@&#39;localhost&#39;; -- 查看用户权限</th></tr></thead></table><h3 id="细粒度访问控制" tabindex="-1">细粒度访问控制 <a class="header-anchor" href="#细粒度访问控制" aria-label="Permalink to &quot;细粒度访问控制&quot;">​</a></h3><ul><li>行级权限控制：通过视图（View）或存储过程限制用户可访问的行。</li></ul><table tabindex="0"><thead><tr><th>SQLCREATE VIEW hr_approved_employees AS SELECT * FROM employees WHERE department = &#39;HR&#39;;GRANT SELECT ON hr_approved_employees TO &#39;hr_user&#39;; -- 仅HR用户可查看本部门数据</th></tr></thead></table><ul><li>列级权限控制：限制用户对特定字段的访问。</li></ul><table tabindex="0"><thead><tr><th>SQLGRANT SELECT (id, name) ON employees TO &#39;public_user&#39;; -- 用户仅可查询ID和姓名列</th></tr></thead></table><h2 id="用户和角色" tabindex="-1">用户和角色 <a class="header-anchor" href="#用户和角色" aria-label="Permalink to &quot;用户和角色&quot;">​</a></h2><p>在数据库系统中，用户与角色是实现权限精细化管控的核心要素，二者协同配合可大幅简化权限管理流程。其中用户是访问数据库的具体实体，角色则是一组权限的逻辑集合，通过将角色批量分配给用户，能够有效规避为单个用户逐一授权的繁琐操作，适配复杂组织结构的权限管理需求。</p><h2 id="用户-user" tabindex="-1">用户（User） <a class="header-anchor" href="#用户-user" aria-label="Permalink to &quot;用户（User）&quot;">​</a></h2><p>用户是数据库系统中被授予访问权限的具体实体，通常对应实际业务中的自然人或需要访问数据库的应用程序，所有用户均需通过密码、数字证书等身份验证方式完成登录，方可获得数据库访问资格。数据库中针对用户的核心管理操作及对应 MySQL 示例语句如下：</p><ol><li>创建用户：CREATE USER &#39;developer&#39;@&#39;localhost&#39; IDENTIFIED BY &#39;password123&#39;;</li><li>修改用户密码：ALTER USER &#39;developer&#39;@&#39;localhost&#39; IDENTIFIED BY &#39;new_password&#39;;</li><li>删除用户：DROP USER &#39;developer&#39;@&#39;localhost&#39;;</li><li>查看用户权限：SHOW GRANTS FOR &#39;developer&#39;@&#39;localhost&#39;;</li></ol><p>具体的SQL代码如下所示：</p><table tabindex="0"><thead><tr><th>SQL-- 创建用户（MySQL示例）CREATE USER &#39;developer&#39;@&#39;localhost&#39; IDENTIFIED BY &#39;password123&#39;;-- 修改用户密码ALTER USER &#39;developer&#39;@&#39;localhost&#39; IDENTIFIED BY &#39;new_password&#39;;-- 删除用户DROP USER &#39;developer&#39;@&#39;localhost&#39;;SHOW GRANTS FOR &#39;developer&#39;@&#39;localhost&#39;; -- 查看用户当前权限</th></tr></thead></table><h2 id="角色-role" tabindex="-1">角色（Role） <a class="header-anchor" href="#角色-role" aria-label="Permalink to &quot;角色（Role）&quot;">​</a></h2><p>角色是数据库中权限的逻辑分组，也是实现批量权限管理的核心载体，其核心作用是将一组相关权限整合为一个整体，再统一分配给多个用户，避免为每个用户单独配置权限的重复工作，提升权限管理的效率和规范性。数据库中针对角色的核心管理操作及对应示例语句如下：</p><ol><li>创建角色：CREATE ROLE &#39;data_analyst&#39;;</li><li>为角色授予权限：GRANT SELECT, INSERT, UPDATE ON sales_data.* TO &#39;data_analyst&#39;;</li><li>将角色分配给用户：GRANT &#39;data_analyst&#39; TO &#39;user1&#39;@&#39;localhost&#39;, &#39;user2&#39;@&#39;localhost&#39;;</li><li>激活角色：SET ROLE &#39;data_analyst&#39;;（部分数据库系统需显式激活角色，权限方可生效）</li><li>删除角色：DROP ROLE &#39;data_analyst&#39;;</li></ol><p>具体的SQL代码如下所示：</p><table tabindex="0"><thead><tr><th>SQL-- 创建角色CREATE ROLE &#39;data_analyst&#39;;-- 为角色授予权限GRANT SELECT, INSERT, UPDATE ON sales_data.* TO &#39;data_analyst&#39;;-- 将角色分配给用户GRANT &#39;data_analyst&#39; TO &#39;user1&#39;@&#39;localhost&#39;, &#39;user2&#39;@&#39;localhost&#39;;-- 激活角色（某些数据库需显式激活）SET ROLE &#39;data_analyst&#39;;-- 删除角色DROP ROLE &#39;data_analyst&#39;;</th></tr></thead></table><h2 id="用户与角色的关系" tabindex="-1">用户与角色的关系 <a class="header-anchor" href="#用户与角色的关系" aria-label="Permalink to &quot;用户与角色的关系&quot;">​</a></h2><p>用户与角色之间为多对多的关联关系，且具备权限继承的特性，这也是二者协同实现高效权限管理的核心逻辑：一方面，单个用户可被分配多个角色，从而同时拥有多组权限，例如某用户可同时拥有data_analyst和report_generator两个角色的全部权限；另一方面，单个角色可被分配给多个用户，实现权限的批量复用，例如多个数据分析人员可共享data_analyst角色的权限。而在权限继承层面，用户会自动获得其所关联角色的全部权限，当角色的权限发生新增、修改或回收时，所有关联该角色的用户权限会同步自动更新，无需对每个用户单独操作。</p><h2 id="真题-1" tabindex="-1">真题 <a class="header-anchor" href="#真题-1" aria-label="Permalink to &quot;真题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>【国家电网2018】下列 SQL 语句中，能够实现&quot;收回用户 ZHAO 对学生表(STUD)中学号(XH)的修改权&quot;这一功能的是（）A. REVOKE UPDATE(XH) ON TABLE FROM ZHAOB. REVOKE UPDATE(XH) ON TABLE FROM PUBLICC. REVOKE UPDATE(XH) ON STUD FROM ZHAOD. REVOKE UPDATE(XH) ON STUD FROM PUBLIC答案 ：C解析 ：收回权限的语法为REVOKE权限ON表名FROM用户，需指定具体表名（STUD）和用户（ZHAO）</th></tr></thead></table><table tabindex="0"><thead><tr><th>【中国铁塔2019】将查询 Student 表的权限授予用户 User1，并允许该用户将此权限授予其他用户。实现此功能的 SQL 语句是（）A. Grant Select To Table Student On User1 With Public；B. Grant Select On Table Student To User1 With Public；C. Grant Select On Table Student To User1 With Grant Option；D. Grant Select To Table Student On User1 With Grant Option答案 ：C解析 ：授予权限并允许转授的语法为Grant权限On表名To用户With Grant Option</th></tr></thead></table><h2 id="dba与审计" tabindex="-1">DBA与审计 <a class="header-anchor" href="#dba与审计" aria-label="Permalink to &quot;DBA与审计&quot;">​</a></h2><h2 id="dba-数据库管理员" tabindex="-1">DBA（数据库管理员） <a class="header-anchor" href="#dba-数据库管理员" aria-label="Permalink to &quot;DBA（数据库管理员）&quot;">​</a></h2><h3 id="dba是什么" tabindex="-1">DBA是什么？ <a class="header-anchor" href="#dba是什么" aria-label="Permalink to &quot;DBA是什么？&quot;">​</a></h3><p>DBA（Database Administrator，数据库管理员）是负责数据库系统全生命周期管理的专业技术人员，核心工作覆盖数据库的规划、设计、部署、维护与优化，最终目标是保障数据库的可用性、安全性、性能稳定性及数据完整性，为业务系统提供持续、可靠的数据支撑。</p><h3 id="dba的职责" tabindex="-1">DBA的职责 <a class="header-anchor" href="#dba的职责" aria-label="Permalink to &quot;DBA的职责&quot;">​</a></h3><p>DBA 承担着数据库系统全维度的管控职责，核心可归纳为三大方向：一是基础运维管理，包括数据库的安装部署、日常监控、数据备份与灾难恢复，确保数据库系统稳定运行；二是安全管控，涵盖用户密码管理、访问权限分配、资源配额设定等，筑牢数据库安全防线；三是规范与设计，包括数据库架构设计、SQL 语句规范制定，以及通过监控警告日志及时发现并解决潜在问题，保障数据库设计与使用的规范性。</p><h2 id="审计" tabindex="-1">审计 <a class="header-anchor" href="#审计" aria-label="Permalink to &quot;审计&quot;">​</a></h2><h3 id="数据库审计是什么" tabindex="-1">数据库审计是什么？ <a class="header-anchor" href="#数据库审计是什么" aria-label="Permalink to &quot;数据库审计是什么？&quot;">​</a></h3><p>数据库审计是保障数据安全的核心监控机制，通过全面捕获并存储数据库的所有访问行为、操作内容及执行结果，对数据库操作进行全流程记录、分析与监控，核心目标是实现数据操作的可追溯性，既满足行业合规要求，也能有效防范内外部非授权操作带来的风险。</p><h3 id="审计的核心功能" tabindex="-1">审计的核心功能 <a class="header-anchor" href="#审计的核心功能" aria-label="Permalink to &quot;审计的核心功能&quot;">​</a></h3><table tabindex="0"><thead><tr><th>核心功能</th><th>具体内容</th><th>应用场景</th></tr></thead><tbody><tr><td>操作记录</td><td>记录用户对数据库的增删改查（CRUD）、DDL（表结构变更）、权限修改等操作</td><td>追踪数据泄露源头、定位误操作责任人</td></tr><tr><td>用户行为监控</td><td>监控用户登录/登出、会话时长、异常登录（如异地IP、高频失败登录）</td><td>防范暴力破解、账号盗用等安全事件</td></tr><tr><td>风险行为识别</td><td>识别高危操作（如删除核心表、批量导出敏感数据）、异常查询模式（如SQL注入特征）</td><td>实时阻断或告警潜在攻击，减少数据损失</td></tr><tr><td>合规审计报表</td><td>生成符合监管要求的审计报告（如操作频率、敏感数据访问统计）</td><td>满足等保2.0、GDPR、PCI DSS等合规审计要求</td></tr><tr><td>数据追溯与取证</td><td>提供操作时间、用户、IP、SQL语句及影响数据量的完整日志，支持事后取证分析</td><td>司法调查、内部审计或故障定位时还原操作场景</td></tr></tbody></table><h2 id="真题-2" tabindex="-1">真题 <a class="header-anchor" href="#真题-2" aria-label="Permalink to &quot;真题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>【国家电网2019】数据库的安全性是指保护数据库以防止不合法的使用所造成的数据泄露、更改或破坏。所以通过提供授权功能来控制不同用户访问数据的权限，是为了实现数据库的()；A. 完整性 B. 安全性 C. 并发控制 D. 恢复答案 ：B解析 ：数据库的安全性是指保护数据库以防止不合法的使用所造成的数据泄露、更改或破坏。通过提供授权功能控制不同用户访问数据的权限，是实现数据库安全性的手段</th></tr></thead></table><table tabindex="0"><thead><tr><th>【国家电网】以下属于实现数据库系统安全性的主要技术和方法的是（ ）A.存取控制技术B.视图技术C.审计技术D.出入机房登记和加锁答案 ：ABC解析 ：实现数据库系统安全性的主要技术包括存取控制技术、视图技术、审计技术等，出入机房登记属于环境级安全措施，不是数据库系统本身的技术。</th></tr></thead></table><h2 id="数据加密" tabindex="-1">数据加密 <a class="header-anchor" href="#数据加密" aria-label="Permalink to &quot;数据加密&quot;">​</a></h2><h2 id="数据加密概念" tabindex="-1">数据加密概念 <a class="header-anchor" href="#数据加密概念" aria-label="Permalink to &quot;数据加密概念&quot;">​</a></h2><p>数据库数据加密是通过加密算法对数据进行处理，保护数据在存储、传输、处理全生命周期中不被未授权访问、窃取或篡改的核心安全手段，其价值主要体现在三个层面：一是合规层面，满足 GDPR、HIPAA、等保 2.0 等行业法规对身份证号、金融信息等敏感数据的加密要求，规避数据泄露引发的法律风险；二是风控层面，即便数据库被入侵或管理员权限被滥用，加密后的密文数据也能大幅降低数据被窃取、篡改的风险；三是隐私保护层面，在数据共享、外包处理或云存储等非可信环境中，加密可确保数据安全，避免隐私泄露。</p><h2 id="数据加密的主要类型" tabindex="-1">数据加密的主要类型 <a class="header-anchor" href="#数据加密的主要类型" aria-label="Permalink to &quot;数据加密的主要类型&quot;">​</a></h2><ol><li>存储加密（静态数据加密）：针对磁盘上的数据库文件、日志文件等静态数据加密，防止存储介质被窃取导致数据泄露。实现方式包括数据库内置加密（如 Oracle TDE、SQL Server Always Encrypted，支持表 / 列 / 全库加密）、操作系统级加密（如 BitLocker、LUKS 磁盘分区加密）、文件系统级加密（如 NTFS-EFS、EXT4 加密）。</li><li>传输加密（动态数据加密）：对数据库客户端与服务器、节点间传输的动态数据加密，防范网络窃听。主流实现方式为 SSL/TLS 协议（MySQL、PostgreSQL 均支持），或通过 VPN 通道构建加密通信链路。</li><li>内存加密（处理中数据加密）：对内存中缓存、临时表等处理中的数据加密，防止内存 Dump 或恶意程序读取。可通过硬件层面（如 Intel SGX 可信执行环境）或软件层面（数据库引擎自动加密 / 解密内存数据）实现。</li></ol><h2 id="数据加密关键技术" tabindex="-1">数据加密关键技术 <a class="header-anchor" href="#数据加密关键技术" aria-label="Permalink to &quot;数据加密关键技术&quot;">​</a></h2><ol><li>加密算法选择：对称加密算法（AES、DES/3DES）加密解密共用同一密钥，效率高，适合存储加密等大量数据处理场景；非对称加密算法（RSA、ECC）采用公钥加密、私钥解密，安全性高但效率低，多用于密钥管理（如加密对称密钥）；哈希算法（SHA-256、MD5）用于数据完整性校验（如密码存储），需结合盐值（Salt）防范彩虹表攻击。</li><li>密钥管理：采用分层架构保障密钥安全，主密钥（KM）作为最高层级密钥，用于加密下一层数据加密密钥（DEK），需离线存储于硬件安全模块（HSM）；DEK 用于加密实际数据，可由主密钥加密后存储。同时需做好密钥生命周期管理，定期轮换密钥，并记录密钥生成、分发、更新、销毁的全流程日志，确保可追溯。</li><li>列级加密（细粒度加密）：针对身份证号、信用卡号等敏感列单独加密，不影响非敏感列的查询性能。该方式的核心挑战是加密后数据无法直接索引、排序或模糊查询，需通过保序加密、可搜索加密等 “加密索引” 技术解决。</li></ol><h2 id="ssl协议" tabindex="-1">SSL协议 <a class="header-anchor" href="#ssl协议" aria-label="Permalink to &quot;SSL协议&quot;">​</a></h2><h3 id="什么是ssl协议" tabindex="-1">什么是SSL协议 <a class="header-anchor" href="#什么是ssl协议" aria-label="Permalink to &quot;什么是SSL协议&quot;">​</a></h3><p>SSL（安全套接层）是一种为网络通信提供加密、身份验证与数据完整性保障的安全协议，最初由 Netscape 公司开发，后续逐步演变为标准化的 TLS（传输层安全协议，如 TLS 1.2、TLS 1.3），二者常被统称为 SSL/TLS 协议。其核心目标是在客户端与服务器之间建立一条加密的安全通信通道，防止数据在传输过程中被窃听、篡改或伪造，具体通过三大核心能力实现这一目标：</p><ol><li>加密传输：使用对称加密算法（如 AES）对传输数据加密，确保第三方无法读取内容。</li><li>身份验证：通过数字证书验证服务器身份（可选客户端验证），防止中间人攻击。</li><li>数据完整性：利用哈希算法（如 SHA-256）生成消息认证码（MAC），确保数据未被篡改。</li></ol><h3 id="ssl-协议的工作流程" tabindex="-1">SSL 协议的工作流程 <a class="header-anchor" href="#ssl-协议的工作流程" aria-label="Permalink to &quot;SSL 协议的工作流程&quot;">​</a></h3><p><img src="'+d+'" alt=""></p><p>SSL 协议的通信流程分为三个连贯的阶段，共同完成安全连接的建立、数据传输与关闭：</p><ol><li>握手阶段（建立安全连接）</li></ol><ul><li>客户端问候（ClientHello）：客户端发送支持的 SSL 版本、加密算法列表、随机数等信息。</li><li>服务器问候（ServerHello）：服务器选择 SSL 版本、加密算法，返回证书（含公钥）和随机数。</li><li>客户端验证证书：检查证书有效性（如颁发机构、过期时间），提取服务器公钥。</li><li>客户端生成预主密钥：用服务器公钥加密预主密钥并发送给服务器。</li><li>密钥协商：客户端和服务器通过预主密钥与随机数生成对称加密的会话密钥。</li></ul><ol><li>数据传输阶段：双方使用会话密钥对数据加密传输，并用哈希算法验证数据完整性。</li><li>连接关闭阶段：双方发送关闭通知，终止安全连接。</li></ol><h2 id="真题-3" tabindex="-1">真题 <a class="header-anchor" href="#真题-3" aria-label="Permalink to &quot;真题&quot;">​</a></h2><table tabindex="0"><thead><tr><th>【中国银行2023】下列哪种加密算法被广泛用于保护 Wi-Fi 网络的安全性?()A.TLSB.WEPC.WPAD.SSL答案 ：C解析 ：WPA（Wi-Fi Protected Access）是针对 Wi-Fi 网络设计的加密标准，用于解决 WEP 的安全缺陷；SSL（安全套接层）主要用于 HTTP 等网络通信加密（如 HTTPS），并非专门针对 Wi-Fi 网</th></tr></thead></table><table tabindex="0"><thead><tr><th>【中国银行2023】在计算机安全中，以下哪个技术用于保护敏感数据，确保只有授权用户才能访问()A.防火墙B. 加密C.IDS/IPSD.访问控制答案 ：B解析 ：加密技术通过将敏感数据转换为密文，只有拥有解密密钥的授权用户才能还原为明文，是保护数据保密性的核心手段，可有效防止未授权访问</th></tr></thead></table>',96)])])}const T=t(o,[["render",h]]);export{u as __pageData,T as default};
